class Gateway:
    def __init__(self, directory: UserDirectory, upstream: Upstream, ledger: Ledger,
                 clock: Callable[[], datetime] = _utc_now):
        self.directory = directory
        self.upstream = upstream
        self.ledger = ledger
        self.clock = clock
        # Store successful responses for idempotent replay
        self._idempotent_store: Dict[Tuple[str, str], Response] = {}

    def handle(self, request: dict) -> Response:
        user_id = request.get("user")
        # Unknown user
        try:
            _ = self.directory.get(user_id)
        except KeyError:
            return Response(403, {"error": "unknown_user"})

        model = request.get("model")
        if model not in PRICES:
            return Response(400, {"error": "unknown_model"})

        request_id = request.get("request_id")
        if request_id is not None:
            stored = self._idempotent_store.get((user_id, request_id))
            if stored:
                headers = dict(stored.headers)
                headers["X-Idempotent-Replay"] = "true"
                return Response(stored.status, stored.body, headers)

        month = self.clock().strftime("%Y-%m")
        budget = self.directory.budget(user_id)
        # Admission control: worst case cost
        worst_usage = Usage(prompt_tokens=request.get("input_tokens", 0), cached_tokens=0,
                            completion_tokens=request.get("max_tokens", 0))
        worst_cost = request_cost(model, worst_usage)
        spent = self.ledger.spent(user_id, month)
        if budget is not None and spent + worst_cost > budget:
            remaining = budget - spent
            if remaining < Decimal("0"):
                remaining = Decimal("0")
            return Response(402, {"error": "budget_exceeded", "remaining": f"{remaining.quantize(Decimal('0.000001'))}"})

        attempts = 0
        max_attempts = 3
        while attempts < max_attempts:
            attempts += 1
            try:
                completion = self.upstream(request)
                usage = completion.usage
                cost = request_cost(model, usage)
                entry = Entry(user_id=user_id, month=month, model=model, usage=usage, cost=cost, status="ok")
                self.ledger.record(entry)
                body = {
                    "content": completion.content,
                    "usage": {"prompt_tokens": usage.prompt_tokens, "cached_tokens": usage.cached_tokens,
                              "completion_tokens": usage.completion_tokens},
                    "cost_usd": f"{cost.quantize(Decimal('0.000001'))}",
                }
                headers: Dict[str, str] = {}
                if budget is not None:
                    new_spent = self.ledger.spent(user_id, month)
                    remaining = budget - new_spent
                    if remaining < Decimal("0"):
                        remaining = Decimal("0")
                    headers["X-Budget-Remaining"] = f"{remaining.quantize(Decimal('0.000001'))}"
                    if new_spent >= budget:
                        headers["X-Budget-Warning"] = "100%"
                    elif new_spent >= budget * Decimal("0.8"):
                        headers["X-Budget-Warning"] = "80%"
                response = Response(200, body, headers)
                if request_id is not None:
                    self._idempotent_store[(user_id, request_id)] = response
                return response
            except UpstreamError as e:
                if e.usage is not None:
                    cost = request_cost(model, e.usage)
                    entry = Entry(user_id=user_id, month=month, model=model, usage=e.usage, cost=cost, status="failed_attempt")
                    self.ledger.record(entry)
                if not e.retryable or attempts >= max_attempts:
                    return Response(502, {"error": "upstream_failed", "attempts": attempts})
                # else retry
        return Response(502, {"error": "upstream_failed", "attempts": attempts})

def top_spenders(self, month: str, n: int) -> List[Tuple[str, Decimal]]:
    # Aggregate total cost per user for given month, omit zero cost.
    costs: Dict[str, Decimal] = {}
    for e in self.entries:
        if e.month != month:
            continue
        costs[e.user_id] = costs.get(e.user_id, Decimal("0")) + e.cost
    # Remove zero-cost users
    filtered = [(uid, amt) for uid, amt in costs.items() if amt != Decimal("0")]
    # Sort by cost descending, then user_id ascending
    filtered.sort(key=lambda x: (-x[1], x[0]))
    return filtered[:n]

